102	/// `init` against explicit terminal state, prompter, output streams, and command runner.
103	pub fn run<R: CommandRunner>(
104	    args: InitArgs,
105	    global: &GlobalArgs,
106	    interactive: bool,
107	    prompter: &mut dyn Prompter,
108	    out: &mut dyn Write,
109	    err: &mut dyn Write,
110	    runner: &R,
111	) -> Result<ExitCode, CliError> {
112	    validate_flags(&args)?;
113	    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
114	    let (root, no_root) = match workspace_root(global, runner) {
115	        Ok(root) => (root, None),
116	        Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
117	            toplevel.clone(),
118	            Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
119	        ),
120	        Err(error) => return Err(error),
121	    };
122	    let locator = IgnoreWalkLocator::new(&root);
123	    let facts = scaffold::detect(&root, &locator, runner)?;
124	    if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
125	        return Err(error.into());
126	    }
127	    let json = global.format == OutputFormat::Json;
128	    // JSON keeps stdout for the report.
129	    let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
130	    write_facts(&facts, human)?;
131	
132	    if facts.origin.is_none() {
133	        if args.workflow {
134	            return Err(CliError::InitFlagRequiresOrigin { flag: "workflow" });
135	        }
136	        if !args.artifact_targets.is_empty() {
137	            return Err(CliError::InitFlagRequiresOrigin {
138	                flag: "artifact-target",
139	            });
140	        }
141	    }
142	    if !interactive && !args.yes {
143	        let mut missing = vec!["--yes"];
144	        missing.extend(missing_flags(&args, &facts));
145	        return Err(CliError::InitRequiresYes { missing });
146	    }
147	    if args.yes {
148	        let missing = missing_flags(&args, &facts);
149	        if !missing.is_empty() {
150	            return Err(CliError::InitMissingFlags { missing });
151	        }
152	    }
153	    let prompting = interactive && !args.yes;
154	    let answers = collect_answers(&args, &facts, prompting, prompter)?;
155	
156	    let mut diagnostics = scaffold::changesets_config_diagnostics(&facts.root);
157	    if facts.origin.is_none() {
158	        writeln!(human, "{ORIGIN_MISSING_NOTE}")?;
159	        diagnostics.push(callisto_model::Diagnostic {
160	            code: callisto_model::DiagnosticCode::InitOriginMissing,
161	            severity: callisto_model::DiagnosticSeverity::Warning,
162	            message: ORIGIN_MISSING_NOTE.to_owned(),
163	            package: None,
164	            path: None,
165	            escalated_by: None,
166	            governed_by: None,
167	        });
168	    }
169	    let shape = match scaffold::workflow_shape(&facts, &answers) {
170	        Err(reason) if args.workflow => {
171	            return Err(GraphError::InitWorkflowUnsupported {
172	                reason: reason.to_string(),
173	            }
174	            .into());
175	        }
176	        Err(reason) => {
177	            let note = workflow_unsupported_note(reason);
178	            writeln!(human, "{note}")?;
179	            diagnostics.push(callisto_model::Diagnostic {
180	                code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
181	                severity: callisto_model::DiagnosticSeverity::Warning,
182	                message: note,
183	                package: None,
184	                path: None,
185	                escalated_by: None,
186	                governed_by: None,
187	            });
188	            None
189	        }
190	        Ok(shape) => Some(shape),
191	    };
192	    let want_workflow = match shape {
193	        None => false,
194	        Some(_) if args.workflow => true,
195	        Some(_) if args.no_workflow => false,
196	        Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
197	        // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
198	        Some(_) => facts.origin_repository.is_some(),
199	    };
200	    // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
201	    let asked_for_workflow = args.workflow || prompting;
202	    let workflow = match shape.filter(|_| want_workflow) {
203	        Some(shape) => match build_workflow(&facts, shape, runner, human) {
204	            Ok(built) => Some(built),
205	            Err(error) if !asked_for_workflow => {
206	                let note =
207	                    format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
208	                writeln!(human, "{note}")?;
209	                diagnostics.push(callisto_model::Diagnostic {
210	                    code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
211	                    severity: callisto_model::DiagnosticSeverity::Warning,
212	                    message: note,
213	                    package: None,
214	                    path: None,
215	                    escalated_by: None,
216	                    governed_by: None,
217	                });
218	                None
219	            }
220	            Err(error) => return Err(error),
221	        },
222	        None => None,
223	    };
224	
225	    let config = scaffold::render_config(&facts, &answers);
226	    let plan = if facts.has_commit {
227	        Some(scaffold::preview(&facts, &config, &locator, runner)?)
228	    } else {
229	        None
230	    };
231	    if config
232	        .lines()
233	        .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
234	    {
235	        writeln!(human, "\ncallisto.toml: no settings needed, the defaults apply.")?;
236	    } else {
237	        writeln!(human, "\ncallisto.toml:\n{config}")?;
238	    }
239	    match plan {
240	        Some(plan) => {
241	            writeln!(human, "First release preview (`callisto release --dry-run`):")?;
242	            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human)?;
243	        }
244	        None => writeln!(human, "{NO_COMMITS}")?,
245	    }
246	    if let Some((workflow, _)) = &workflow {
247	        writeln!(
248	            human,
249	            "\n{}:\n{workflow}",
250	            scaffold::workflow_path(&facts.root).display()
251	        )?;
252	    }
253	
254	    // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
255	    let files = scaffold::init_files(&facts.root, workflow.is_some())?;
256	    let mut report = if global.dry_run {
257	        InitReport {
258	            schema_version: SCHEMA_VERSION,
259	            initialized: false,
260	            config_path: facts.root.join("callisto.toml"),
261	            config,
262	            files,
263	            diagnostics: Vec::new(),
264	        }
265	    } else {
266	        if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
267	            writeln!(human, "Initialization cancelled; nothing was written.")?;
268	            return Ok(ExitCode::SUCCESS);
269	        }
270	        let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
271	        let mut report = scaffold::write(&facts.root, &config, &permit)?;
272	        if let Some((workflow, branch)) = &workflow {
273	            scaffold::write_workflow(&facts.root, workflow, &permit)?;
274	            let note = merge_publishes_note(branch);
275	            writeln!(human, "{note}")?;
276	            writeln!(human, "{}", next_steps_note(&scaffold::registry_secret_names(&facts)))?;
277	            diagnostics.push(callisto_model::Diagnostic {
278	                code: callisto_model::DiagnosticCode::WorkflowMergePublishes,
279	                severity: callisto_model::DiagnosticSeverity::Info,
280	                message: note,
281	                package: None,
282	                path: None,
283	                escalated_by: None,
284	                governed_by: None,
285	            });
286	        }
287	        report.files = files;
288	        report
289	    };
290	    report.diagnostics.extend(diagnostics);
291	    if json {
292	        emit_report(&mut &mut *out, &report, global.dry_run)?;
293	    } else {
294	        render::render_init(&report, &mut &mut *out)?;
295	    }
296	    Ok(ExitCode::SUCCESS)
297	}
