339	fn write_facts(facts: &InitFacts, out: &mut dyn Write) -> Result<(), CliError> {
340	    let ecosystems: Vec<&str> = facts.ecosystems.iter().map(|ecosystem| ecosystem.prefix()).collect();
341	    writeln!(out, "Detected:")?;
342	    writeln!(out, "  ecosystems: {}", ecosystems.join(", "))?;
343	    writeln!(out, "  origin: {}", facts.origin.as_deref().unwrap_or("none"))?;
344	    writeln!(out, "  packages:")?;
345	    for package in &facts.packages {
346	        let tag = package.last_tag.as_ref().map_or("none", |tag| tag.as_str());
347	        write!(out, "    {} {} (last tag: {tag}", package.id, package.version)?;
348	        if package.is_binary() {
349	            write!(out, "; binary: {}", package.bin_names.join(", "))?;
350	        }
351	        writeln!(out, ")")?;
352	    }
353	    Ok(())
354	}
