108	            .filter(|package| package.is_binary() && package.supports_artifact_builder())
109	    }
110	
111	    pub fn unsupported_artifact_packages(&self) -> impl Iterator<Item = &InitPackage> {
112	        self.packages
113	            .iter()
114	            .filter(|package| !package.supports_artifact_builder() && !package.unsupported_bin_ecosystems.is_empty())
115	    }
116	
117	    /// Resolves `name` (qualified or bare) to a binary-producing package.
118	    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
119	        let invalid = |reason| GraphError::InitInvalidProductPackage {
120	            package: name.to_owned(),
121	            reason,
122	            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
123	        };
124	        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
125	            Some(package) => vec![package],
126	            None => self.packages.iter().filter(|package| package.name() == name).collect(),
127	        };
128	        match found.as_slice() {
129	            [package] if package.is_binary() && package.supports_artifact_builder() => Ok(package),
130	            [package] if package.is_binary() => Err(GraphError::InitUnsupportedArtifactBuilder {
131	                package: package.id.clone(),
132	                ecosystem: package.unsupported_bin_ecosystems.first().cloned().unwrap_or_else(|| {
133	                    package
134	                        .id
135	                        .split_once('/')
136	                        .map_or("unknown", |(ecosystem, _)| ecosystem)
137	                        .to_owned()
138	                }),
139	            }),
140	            [_] => Err(invalid("it does not produce a binary artifact")),
141	            _ => Err(invalid("it is not a workspace package")),
142	        }
143	    }
144	}
