662	/// The workflow shape `init` generates for this workspace and answers.
663	///
664	/// # Errors
665	///
666	/// The workspace has a shape no generated workflow covers.
667	pub fn workflow_shape(facts: &InitFacts, answers: &InitAnswers) -> Result<WorkflowShape, WorkflowUnsupported> {
668	    if facts.has_maturin_targets {
669	        Err(WorkflowUnsupported::Maturin)
670	    } else if facts.has_platform_packages && !facts.has_napi_targets {
671	        Err(WorkflowUnsupported::PlatformPackagesWithoutNapiTargets)
672	    } else if answers.binaries.is_some() || facts.has_platform_packages {
673	        Ok(WorkflowShape::BuildMatrix)
674	    } else {
675	        Ok(WorkflowShape::Simple)
676	    }
677	}
