782	// actually checked out is a better guess than a hardcoded `main`.
783	fn current_branch<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
784	    let output = runner
785	        .run_quiet(
786	            programs::GIT,
787	            &["symbolic-ref", "--short", "HEAD"],
788	            root,
789	            timeouts::LOCAL_GIT,
790	        )
791	        .ok()?;
792	    if output.exit_code != Some(0) {
793	        return None;
794	    }
795	    let branch = output.stdout.trim();
796	    (!branch.is_empty()).then(|| branch.to_owned())
797	}
