799	// Rendered with `replace`, not `format!`, so `${{ ... }}` needs no escaping; `.tmpl` so it never reads as a workflow.
800	const WORKFLOW_TEMPLATE: &str = include_str!("../templates/simple_workflow.tmpl");
801	
802	const MATRIX_WORKFLOW_TEMPLATE: &str = include_str!("../templates/matrix_workflow.tmpl");
803	
804	const BUILD_REQUIREMENT: &str = "build==1.4.4";
805	const TWINE_REQUIREMENT: &str = "twine==7.0.0";
806	
807	/// Installs the Python build and upload tools into a venv put on the PATH of the later steps; carries no secrets.
808	const SIMPLE_PYTHON_TOOLS_STEP: &str = "      - name: Install the Python publishing tools
809	        run: |
810	          set -euo pipefail
