866	/// The repository secrets the generated workflow reads, one per registry ecosystem the workspace has.
867	pub fn registry_secret_names(facts: &InitFacts) -> Vec<&'static str> {
868	    [
869	        (Ecosystem::Cargo, "CARGO_REGISTRY_TOKEN"),
870	        (Ecosystem::Npm, "NPM_TOKEN"),
871	        (Ecosystem::Pypi, "PYPI_TOKEN"),
872	    ]
873	    .into_iter()
874	    .filter(|(ecosystem, _)| facts.ecosystems.contains(ecosystem))
875	    .map(|(_, name)| name)
876	    .collect()
877	}
878	
879	/// Renders the release workflow for `shape`.
880	///
881	/// `commit` pins the generated `orin-dx/callisto` action references to the
882	/// resolved commit of `callisto@<version>` (see [`resolve_release_commit`]);
883	/// `version` names the CLI `setup-callisto` installs and a trailing comment.
884	pub fn render_workflow(facts: &InitFacts, shape: WorkflowShape, branch: &str, commit: &str, version: &str) -> String {
885	    let mut secrets = Vec::new();
886	    for name in registry_secret_names(facts) {
887	        secrets.push(format!("{name}: ${{{{ secrets.{name} }}}}"));
888	        if name == "NPM_TOKEN" {
889	            // Uses the job's id-token: write; npm publishes no provenance without it.
890	            secrets.push("NPM_CONFIG_PROVENANCE: \"true\"".to_owned());
891	        }
892	    }
893	    secrets.push("GH_TOKEN: ${{ github.token }}".to_owned());
894	    let env_lines: Vec<String> = secrets.iter().map(|line| format!("          {line}")).collect();
895	    let release_env = format!("env:\n{}", env_lines.join("\n"));
896	
897	    let template = match shape {
898	        WorkflowShape::Simple => WORKFLOW_TEMPLATE,
899	        WorkflowShape::BuildMatrix => MATRIX_WORKFLOW_TEMPLATE,
900	    };
901	    let python_tools = if facts.ecosystems.contains(&Ecosystem::Pypi) {
902	        SIMPLE_PYTHON_TOOLS_STEP
903	    } else {
904	        ""
905	    };
906	    template
907	        .replace("      __PYTHON_TOOLS__\n", python_tools)
908	        .replace("__BUILD__", BUILD_REQUIREMENT)
909	        .replace("__TWINE__", TWINE_REQUIREMENT)
910	        .replace("__BRANCH__", branch)
911	        .replace("__COMMIT__", commit)
912	        .replace("__VERSION__", version)
913	        .replace("        __RELEASE_ENV__", &format!("        {release_env}"))
914	}
915	
916	/// Errors if a workflow file already exists at [`workflow_path`], without writing.
917	///
918	/// # Errors
919	///
920	/// A file already exists at that path.
921	pub fn ensure_workflow_absent(root: &Path) -> Result<(), GraphError> {
922	    let path = workflow_path(root);
923	    if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
924	        return Err(GraphError::InitWorkflowExists { path });
925	    }
