712	pub fn default_branch<R: CommandRunner>(runner: &R, root: &Path) -> DefaultBranch {
713	    if let Some(name) = local_origin_head(runner, root) {
714	        return DefaultBranch {
715	            name,
716	            source: DefaultBranchSource::OriginHead,
717	        };
718	    }
719	    if let Some(name) = remote_origin_head(runner, root) {
720	        return DefaultBranch {
721	            name,
722	            source: DefaultBranchSource::RemoteHead,
723	        };
724	    }
725	    if let Some(name) = current_branch(runner, root) {
726	        return DefaultBranch {
727	            name,
728	            source: DefaultBranchSource::CurrentBranch,
729	        };
730	    }
731	    DefaultBranch {
732	        name: "main".to_owned(),
733	        source: DefaultBranchSource::Fallback,
734	    }
735	}
736	
737	/// The last path segment of a `refs/...` line, e.g. `refs/heads/trunk` -> `trunk`.
738	fn last_ref_segment(reference: &str) -> Option<String> {
739	    let branch = reference.trim().rsplit('/').next()?;
740	    (!branch.is_empty()).then(|| branch.to_owned())
741	}
742	
743	// A repository with no `origin/HEAD` (a fresh clone, or one built by hand, as in tests)
744	// fails this on the common path, not just exceptionally.
745	fn local_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
746	    let output = runner
747	        .run_quiet(
748	            programs::GIT,
749	            &["symbolic-ref", "refs/remotes/origin/HEAD"],
750	            root,
751	            timeouts::LOCAL_GIT,
752	        )
753	        .ok()?;
754	    if output.exit_code != Some(0) {
755	        return None;
756	    }
757	    last_ref_segment(&output.stdout)
758	}
759	
760	// A shallow or hand-built clone (or one `remote set-head` never ran on) has no local
761	// `origin/HEAD`; asking the remote directly still resolves it without a fetch.
762	fn remote_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
763	    let output = runner
764	        .run_quiet(
765	            programs::GIT,
766	            &["ls-remote", "--symref", "origin", "HEAD"],
767	            root,
768	            timeouts::GIT_LS_REMOTE,
769	        )
770	        .ok()?;
771	    if output.exit_code != Some(0) {
772	        return None;
773	    }
774	    // Output line shape: "ref: refs/heads/<branch>\tHEAD".
775	    output.stdout.lines().find_map(|line| {
776	        let (target, name) = line.strip_prefix("ref: ")?.split_once('\t')?;
777	        (name.trim() == "HEAD").then(|| last_ref_segment(target))?
778	    })
779	}
780	
781	// No remote at all (e.g. `init` in a repo built by hand with no `origin`): the branch
782	// actually checked out is a better guess than a hardcoded `main`.
783	fn current_branch<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
784	    let output = runner
785	        .run_quiet(
786	            programs::GIT,
787	            &["symbolic-ref", "--short", "HEAD"],
788	            root,
789	            timeouts::LOCAL_GIT,
790	        )
791	        .ok()?;
792	    if output.exit_code != Some(0) {
793	        return None;
794	    }
795	    let branch = output.stdout.trim();
796	    (!branch.is_empty()).then(|| branch.to_owned())
797	}
798	
799	// Rendered with `replace`, not `format!`, so `${{ ... }}` needs no escaping; `.tmpl` so it never reads as a workflow.
800	const WORKFLOW_TEMPLATE: &str = include_str!("../templates/simple_workflow.tmpl");
801	
802	const MATRIX_WORKFLOW_TEMPLATE: &str = include_str!("../templates/matrix_workflow.tmpl");
803	
804	const BUILD_REQUIREMENT: &str = "build==1.4.4";
805	const TWINE_REQUIREMENT: &str = "twine==7.0.0";
806	
807	/// Installs the Python build and upload tools into a venv put on the PATH of the later steps; carries no secrets.
808	const SIMPLE_PYTHON_TOOLS_STEP: &str = "      - name: Install the Python publishing tools
809	        run: |
810	          set -euo pipefail
811	          python3 -m venv \"$RUNNER_TEMP/publish-venv\"
812	          \"$RUNNER_TEMP/publish-venv/bin/python\" -m pip install --quiet __BUILD__ __TWINE__
813	          echo \"$RUNNER_TEMP/publish-venv/bin\" >> \"$GITHUB_PATH\"
814	";
815	
816	/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
817	///
818	/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
819	/// string (`ActionManifestManagerWrapper.ParseActionReference` in
820	/// `actions/runner`), so a ref that itself contains `@` -- like the
821	/// `callisto@<version>` tag this project releases under -- can never be
822	/// written directly as `owner/repo/path@callisto@<version>`: the split lands
823	/// inside the ref, not before it, and resolution fails. The generated
824	/// workflow pins to this tag's resolved commit instead, like every other
825	/// external action reference in this repository.
826	///
827	/// # Errors
828	///
829	/// The remote is unreachable, or `callisto@<version>` is not a published tag.
830	pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
831	    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
832	    let reference = format!("refs/tags/callisto@{version}");
833	    // The peeled ref resolves an annotated tag to its commit; a lightweight
834	    // tag has no peeled line, and its own SHA already is the commit.
835	    let peeled = format!("{reference}^{{}}");
836	    // A transport-level failure (git not found, timed out, ...) keeps its
837	    // real cause via `GraphError::Command`; only a clean run that still
838	    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
839	    let output = runner.run_quiet(
840	        programs::GIT,
841	        &["ls-remote", ENDPOINT, &reference, &peeled],
842	        root,
843	        timeouts::GIT_LS_REMOTE,
844	    )?;
845	    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
846	        version: version.to_owned(),
847	    };
848	    if output.exit_code != Some(0) {
849	        return Err(unresolved());
850	    }
851	    let mut tag_object = None;
852	    let mut commit = None;
853	    for line in output.stdout.lines() {
854	        let Some((sha, found)) = line.split_once('\t') else {
855	            continue;
856	        };
857	        match found.trim() {
858	            found if found == peeled => commit = Some(sha.trim().to_owned()),
859	            found if found == reference => tag_object = Some(sha.trim().to_owned()),
860	            _ => {}
861	        }
862	    }
863	    commit.or(tag_object).ok_or_else(unresolved)
864	}
865	
866	/// The repository secrets the generated workflow reads, one per registry ecosystem the workspace has.
867	pub fn registry_secret_names(facts: &InitFacts) -> Vec<&'static str> {
868	    [
869	        (Ecosystem::Cargo, "CARGO_REGISTRY_TOKEN"),
870	        (Ecosystem::Npm, "NPM_TOKEN"),
871	        (Ecosystem::Pypi, "PYPI_TOKEN"),
872	    ]
873	    .into_iter()
874	    .filter(|(ecosystem, _)| facts.ecosystems.contains(ecosystem))
875	    .map(|(_, name)| name)
876	    .collect()
877	}
878	
879	/// Renders the release workflow for `shape`.
880	///
881	/// `commit` pins the generated `orin-dx/callisto` action references to the
882	/// resolved commit of `callisto@<version>` (see [`resolve_release_commit`]);
883	/// `version` names the CLI `setup-callisto` installs and a trailing comment.
884	pub fn render_workflow(facts: &InitFacts, shape: WorkflowShape, branch: &str, commit: &str, version: &str) -> String {
885	    let mut secrets = Vec::new();
886	    for name in registry_secret_names(facts) {
887	        secrets.push(format!("{name}: ${{{{ secrets.{name} }}}}"));
888	        if name == "NPM_TOKEN" {
889	            // Uses the job's id-token: write; npm publishes no provenance without it.
890	            secrets.push("NPM_CONFIG_PROVENANCE: \"true\"".to_owned());
891	        }
892	    }
893	    secrets.push("GH_TOKEN: ${{ github.token }}".to_owned());
894	    let env_lines: Vec<String> = secrets.iter().map(|line| format!("          {line}")).collect();
895	    let release_env = format!("env:\n{}", env_lines.join("\n"));
896	
897	    let template = match shape {
898	        WorkflowShape::Simple => WORKFLOW_TEMPLATE,
899	        WorkflowShape::BuildMatrix => MATRIX_WORKFLOW_TEMPLATE,
900	    };
901	    let python_tools = if facts.ecosystems.contains(&Ecosystem::Pypi) {
902	        SIMPLE_PYTHON_TOOLS_STEP
903	    } else {
904	        ""
905	    };
906	    template
907	        .replace("      __PYTHON_TOOLS__\n", python_tools)
908	        .replace("__BUILD__", BUILD_REQUIREMENT)
909	        .replace("__TWINE__", TWINE_REQUIREMENT)
910	        .replace("__BRANCH__", branch)
911	        .replace("__COMMIT__", commit)
912	        .replace("__VERSION__", version)
913	        .replace("        __RELEASE_ENV__", &format!("        {release_env}"))
914	}
915	
916	/// Errors if a workflow file already exists at [`workflow_path`], without writing.
917	///
918	/// # Errors
919	///
920	/// A file already exists at that path.
921	pub fn ensure_workflow_absent(root: &Path) -> Result<(), GraphError> {
922	    let path = workflow_path(root);
923	    if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
924	        return Err(GraphError::InitWorkflowExists { path });
925	    }
926	    Ok(())
927	}
928	
929	/// Writes the generated release workflow.
930	///
931	/// # Errors
932	///
933	/// A workflow file already exists at [`workflow_path`], or the write fails.
934	pub fn write_workflow(root: &Path, content: &str, permit: &ApplyPermit) -> Result<(), GraphError> {
935	    ensure_workflow_absent(root)?;
936	    let path = workflow_path(root);
937	    callisto_model::atomic::atomic_write(&path, content, permit).map_err(io_err(&path))
938	}

